// 场景：用右子树最小节点替换被删节点
let minNode = findMin(node.right);
node.val = minNode.val; // 步骤 1：覆盖数据

// 错误的指针赋值顺序
minNode = minNode.right; // 步骤 2：局部变量指向右子，原 minNode 引用丢失
delete minNode;          // 步骤 3：误删了右子节点，原 minNode 内存泄漏！

// 正确顺序应为：
// let rightChild = minNode.right;
// delete minNode;
// parentOfMin.left = rightChild;
